from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    w = len(g[0])
    for row in g:
        # Extend each horizontal colored bar that starts at the left edge
        # and ends before the right edge with the marker color 1.
        if row and row[0] != bg:
            color = row[0]
            end = 0
            while end < w and row[end] == color:
                end += 1
            if end < w and all(v == bg for v in row[end:]):
                row[end:] = [1] * (w - end)
    return g

def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        if len(set(row)) <= 1:
            continue
        color = row[-1]
        j = len(row) - 1
        while j >= 0 and row[j] == color:
            row[j] = 1
            j -= 1
    return out

